sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float2 center;
uniform float maxRadius;
uniform float ringWidth;
uniform float strength;
uniform float brightness;
uniform float chroma;
uniform float curve;
uniform float opacity;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float e = pow(saturate(beat), curve);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float dist = length(d);
    float2 dir = d / max(dist, 0.001);
    float r0 = (1.0 - beat) * maxRadius * length(size) * 0.5;
    float w = exp(-pow((dist - r0) / max(ringWidth, 1.0), 2.0)) * e;
    float2 off = dir * w * strength;
    float4 cr = tex(coord - off * (1.0 + chroma));
    float4 cg = tex(coord - off);
    float4 cb = tex(coord - off * (1.0 - chroma));
    float4 r = float4(cr.r, cg.g, cb.b, cg.a);
    r = float4(r.rgb * (1.0 + w * brightness), r.a);
    return fin(c, r, opacity);
}
